steps.run:
$ErrorActionPreference = 'Stop'
New-Item -ItemType Directory -Force -Path 'C:\ProgramData\tc-wg-fake', 'C:\Program Files\WireGuard' | Out-Null
# Prints the lines of latest-handshakes.txt (or allowed-ips.txt) beside it; NOW and OLD become the current Unix time and an hour ago
Add-Type -OutputType ConsoleApplication -OutputAssembly 'C:\Program Files\WireGuard\wg.exe' -TypeDefinition @'
using System; using System.IO;
public static class FakeWg {
    public static int Main(string[] a) {
        if (a.Length != 3 || a[0] != "show") { Console.Error.WriteLine("fake wg: only 'show <tunnel> <field>'"); return 1; }
        string f = Path.Combine(@"C:\ProgramData\tc-wg-fake", a[2] + ".txt");
        long now = (long)(DateTime.UtcNow - new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc)).TotalSeconds;
        if (File.Exists(f)) foreach (string l in File.ReadAllLines(f))
            Console.WriteLine(l.Replace("NOW", now.ToString()).Replace("OLD", (now - 3600).ToString()));
        return 0;
    }
}
'@
if (-not (Test-Path -LiteralPath 'C:\Program Files\WireGuard\wg.exe')) { 'fake wg.exe was not built'; exit 1 }
'fake wg.exe built'

$ErrorActionPreference = 'Stop'
# A service that does nothing but start and stop, standing in for the tunnel
Add-Type -OutputType ConsoleApplication -OutputAssembly 'C:\ProgramData\tc-wg-fake\tunnel-service.exe' -ReferencedAssemblies System.ServiceProcess -TypeDefinition @'
using System.ServiceProcess;
public class FakeTunnel : ServiceBase {
    public static void Main() { ServiceBase.Run(new FakeTunnel { ServiceName = "FakeTunnel" }); }
}
'@
New-Service -Name 'WireGuardTunnel$tctest' -BinaryPathName '"C:\ProgramData\tc-wg-fake\tunnel-service.exe"' -StartupType Automatic | Out-Null
Set-Content -LiteralPath 'C:\ProgramData\tc-wg-fake\latest-handshakes.txt' -Value "fakepeer=`tNOW"
Start-Service -Name 'WireGuardTunnel$tctest'
'service ' + (Get-Service -Name 'WireGuardTunnel$tctest').Status
